return out;`}); for (const c of r.content) if (c.type === "text") text(c.text);

arguments.code:
const queries = [
  ["vercel_api", "integration resource"],
  ["vercel_api", "project environment"],
  ["vercel_api", "deployment protection bypass"],
  ["vercel_api", "deployment create"],
  ["sendblue_api", "webhook"],
  ["sendblue_api", "message send"],
  ["sendblue_api", "phone number"],
  ["sendblue_api", "account"]
];
const out = [];
for (const [namespace, query] of queries) {
  const result = await tools.search({ namespace, query, limit: 50 });
  out.push({ namespace, query, total: result.total, items: result.items.map((item) => ({ path: item.path, description: item.description })) });
}
return out;

