const r = await tools.mcp__executor_personal__execute({code:`const teamId = "REDACTED";
const projectId = "REDACTED";
const previewTarget = ["preview"];

const [envResult, messageResult] = await Promise.all([
  tools.vercel_api.user.personalvercelapi.projects.filterProjectEnvs({
    idOrName: projectId,
    teamId,
    decrypt: "true"
  }),
  tools.sendblue_api.user.personalsendblueapi.messages.getMessagesV2({
    limit: 100,
    order_by: "createdAt",
    order_direction: "desc",
    service: "iMessage"
  })
]);

if (!envResult.ok) return { phase: "read", service: "vercel-env", code: envResult.error.code, status: envResult.error.status ?? null };
if (!messageResult.ok) return { phase: "read", service: "sendblue-messages", code: messageResult.error.code, status: messageResult.error.status ?? null };

const envs = "envs" in envResult.data ? envResult.data.envs : [envResult.data];
const byKey = new Map(envs.map((env) => [env.key, env]));
const kvUrl = byKey.get("KV_REST_API_URL")?.value;
const kvToken = byKey.get("KV_REST_API_TOKEN")?.value;
if (!kvUrl || !kvToken) return { phase: "read", code: "missing_preview_kv_values" };

const messages = messageResult.data.data ?? [];
const lineCandidates = messages.filter((message) =>
  [message.sendblue_number, message.from_number, message.to_number].some((number) => number?.endsWith("0577"))
);
const counterpartCandidates = messages.filter((message) =>
  !message.is_outbound &&
  message.service === "iMessage" &&
  [message.from_number, message.number].some((number) => number?.endsWith("7386"))
);
const line = lineCandidates.flatMap((message) => [message.sendblue_number, message.from_number, message.to_number]).find((number) => number?.endsWith("0577"));
const counterpart = counterpartCandidates.flatMap((message) => [message.from_number, message.number]).find((number) => number?.endsWith("7386"));
if (!line || !counterpart) {
  return {
    phase: "read",
    code: "required_line_or_counterpart_not_found",
    lineCandidateCount: lineCandidates.length,
    counterpartCandidateCount: counterpartCandidates.length
  };
}

const config = [
  { key: "BUNDJIL_SENDBLUE_REPLAY_STORE_URL", value: kvUrl, type: "sensitive", target: previewTarget },
  { key: "BUNDJIL_SENDBLUE_REPLAY_STORE_TOKEN", value: kvToken, type: "sensitive", target: previewTarget },
  { key: "BUNDJIL_SENDBLUE_FROM_NUMBER", value: line, type: "sensitive", target: previewTarget },
  { key: "BUNDJIL_SENDBLUE_SENDER_IDENTITIES", value: JSON.stringify([{ phoneNumber: counterpart, principalId: "personal-preview-owner" }]), type: "sensitive", target: previewTarget },
  { key: "BUNDJIL_SENDBLUE_ALLOWED_SERVICES", value: JSON.stringify(["iMessage"]), type: "encrypted", target: previewTarget },
  { key: "BUNDJIL_SENDBLUE_REPLAY_STORE_PREFIX", value: "bundjil:sendblue:preview:", type: "encrypted", target: previewTarget },
  { key: "BUNDJIL_SENDBLUE_REPLAY_STORE_TTL_SECONDS", value: "86400", type: "encrypted", target: previewTarget },
  { key: "BUNDJIL_SENDBLUE_REPLAY_STORE_LEASE_SECONDS", value: "300", type: "encrypted", target: previewTarget }
];

const configResult = await tools.vercel_api.user.personalvercelapi.projects.createProjectEnv({
  idOrName: projectId,
  teamId,
  upsert: "true",
  body: config
});
if (!configResult.ok) return { phase: "configure", service: "vercel-env", code: configResult.error.code, status: configResult.error.status ?? null };

const bypassResult = await tools.vercel_api.user.personalvercelapi.projects.updateProjectProtectionBypass({
  idOrName: projectId,
  teamId,
  body: { generate: { note: "Sendblue Preview receive webhook automation bypass" } }
});
if (!bypassResult.ok) return { phase: "protection", service: "vercel-bypass", code: bypassResult.error.code, status: bypassResult.error.status ?? null };

const created = Array.isArray(configResult.data.created) ? configResult.data.created : [configResult.data.created];
const failed = configResult.data.failed ?? [];
return {
  phase: "complete",
  env: {
    requested: config.map((entry) => entry.key),
    createdOrUpdated: created.map((entry) => ({ key: entry.key, target: entry.target, type: entry.type })),
    failedCount: failed.length
  },
  sendblue: {
    lineSuffix: line.slice(-4),
    counterpartSuffix: counterpart.slice(-4),
    service: "iMessage",
    messageSampleCount: messages.length
  },
  bypass: {
    status: bypassResult.http?.status ?? null,
    configured: Boolean(bypassResult.data.protectionBypass),
    secretNeedsOnePasswordStorage: true
  }
};`}); for (const c of r.content) if (c.type === "text") text(c.text);

