   191	      replay.retryable(decision.claim).pipe(Effect.andThen(Effect.fail(error)))
   192	    )
   193	  );
   194	  return yield* replay
   195	    .complete(decision.claim)
   196	    .pipe(
   197	      Effect.catchTag("SendblueReplayStoreError", (completeError) =>
   198	        replay
   199	          .uncertain(decision.claim)
   200	          .pipe(Effect.andThen(Effect.fail(completeError)))
