   205	export const deliverCompletedMessage = Effect.fn(
   206	  "SendblueChannel.deliverCompletedMessage"
   207	)(function* (input: SendblueCompletedMessageType) {
   208	  const completed = yield* Schema.decodeUnknownEffect(SendblueCompletedMessage)(
   209	    input
   210	  ).pipe(
   211	    Effect.mapError(
   212	      () =>
   213	        new SendblueRoutingError({
   214	          message: "The completed Eve message is invalid.",
   215	        })
   216	    )
   217	  );
   218	  if (
   219	    completed.finishReason === "tool-calls" ||
   220	    completed.message === null ||
   221	    completed.message.trim().length === 0
   222	  ) {
   223	    return "ignored";
   224	  }
   225	  const replay = yield* SendblueReplayStore;
   226	  const client = yield* SendblueClient;
   227	  const claimed = yield* replay.claimOutbound({
   228	    sequence: completed.sequence,
   229	    sessionId: completed.sessionId,
   230	    stepIndex: completed.stepIndex,
   231	    turnId: completed.turnId,
   232	  });
   233	  if (claimed.status === "duplicate") {
   234	    return "duplicate";
   235	  }
   236	  return yield* Schema.decodeUnknownEffect(SendblueSendMessageInput)({
   237	    content: completed.message.trim(),
   238	    from_number: completed.state.sendblueNumber,
   239	    number: completed.state.senderNumber,
   240	  }).pipe(
   241	    Effect.mapError(
   242	      () =>
   243	        new SendblueRequestError({
   244	          message: "The completed Eve message cannot be sent by Sendblue.",
   245	          operation: "sendMessage",
   246	          reason: "requestEncoding",
   247	        })
   248	    ),
   249	    Effect.flatMap(client.sendMessage),
   250	    Effect.tap((success) =>
   251	      replay
   252	        .complete(claimed.claim, {
   253	          providerMessageHandle: success.message_handle,
   254	        })
   255	        .pipe(
   256	          Effect.catchTag("SendblueReplayStoreError", (completeError) =>
   257	            replay
   258	              .uncertain(claimed.claim)
   259	              .pipe(Effect.andThen(Effect.fail(completeError)))
   260	          )
   261	        )
   262	    ),
   263	    Effect.as("delivered" as const),
   264	    Effect.catchTag("SendblueDeliveryUncertainError", (error) =>
   265	      replay.uncertain(claimed.claim).pipe(Effect.andThen(Effect.fail(error)))
   266	    ),
   267	    Effect.catchTag("SendblueRequestError", (error) =>
   268	      replay.retryable(claimed.claim).pipe(Effect.andThen(Effect.fail(error)))
   269	    ),
   270	    Effect.catchTag("SendblueResponseError", (error) =>
   271	      (error.reason === "malformedResponse"
   272	        ? replay.uncertain(claimed.claim)
   273	        : replay.retryable(claimed.claim)
   274	      ).pipe(Effect.andThen(Effect.fail(error)))
   275	    )
   276	  );
   277	});
